4	import React, { useRef, useState } from 'react';
5	import { useIntl } from 'react-intl';
6	import {
7	  useMultiStyleConfig,
8	  Box,
9	  Flex,
10	  IconButton,
11	  Badge,
12	  Button,
13	  Popover,
14	  PopoverHeader,
15	  PopoverTrigger,
16	  PopoverContent,
17	  PopoverBody,
18	  PopoverFooter,
19	  PopoverArrow,
20	  Stack,
21	  Text,
22	  Divider,
23	  useDisclosure,
24	  // useMediaQuery, // unused after layout change
25	} from '@salesforce/retail-react-app/app/components/shared/ui';
26	import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';
27	
28	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
29	
30	import Link from '@salesforce/retail-react-app/app/components/link';
31	import Search from '@salesforce/retail-react-app/app/components/search'; // TEMP: re-enabled for search API debugging
32	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
33	// AccountIcon and HeartIcon are imported but not rendered. They serve the commented-out
34	// base SFCC icon-button block further down this file (search: IconButtonWithRegistration).
35	// That block was disabled when this file was first copied into overrides/ per the copy-first
36	// rule, and is superseded by the Account | Saved | Bag *text* buttons the Zimmermann header
37	// design uses instead — see the "Desktop right" block below. HPC-018 (Confirmed) requires
38	// Search / Account / Bag in the header, with no breakpoint qualification, and Account is
39	// present as text only at `lg`+ via that block.
40	//
41	// Below `lg` the header renders Search / Store Locator (when `storeLocatorEnabled`) / Bag.
42	// Account is still *reachable* there — base `drawer-menu` carries "My Account" and "Sign In",
43	// opened by the mobile-only hamburger — but no PRD confirms the drawer as HPC-018's intended
44	// satisfaction, so treat that as an open question rather than as compliance. Two discrepancies
45	// against HPC-018 below `lg`, both tracked separately and neither resolved here: Account is
46	// absent from the header the requirement names, and Store Locator is present although
47	// homepage.md:19 says "Locate Boutique ... not part of the header".
48	// Kept as a reference to the base implementation, per AGENTS.md's rule on commented-out code.
49	import {
50	  AccountIcon,
51	  BasketIcon,
52	  BrandLogo,
53	  HamburgerIcon,
54	  ChevronDownIcon,
55	  HeartIcon,
56	  SearchIcon,
57	  SignoutIcon,
58	  StoreIcon,
59	  SparkleIcon,
60	} from '@salesforce/retail-react-app/app/components/icons';
61	
62	import { navLinks, messages } from '@salesforce/retail-react-app/app/pages/account/constant';
63	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
64	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
65	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
66	// import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive'; // replaced by inline display props
67	import { isHydrated, noop } from '@salesforce/retail-react-app/app/utils/utils';
68	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
69	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
70	
71	// Unused: serves the commented-out base icon-button block below — see the note on the
72	// icons import above.
73	const IconButtonWithRegistration = withRegistration(IconButton);
74	const ButtonWithRegistration = withRegistration(Button);
75	
76	type HeaderProps = {
77	  children?: React.ReactNode;
78	  onMenuClick?: () => void;
79	  onLogoClick?: () => void;
80	  onMyAccountClick?: () => void;
81	  onWishlistClick?: () => void;
82	  onMyCartClick?: () => void;
83	  onStoreLocatorClick?: () => void;
84	  onAgentClick?: () => void;
85	  searchInputRef?: React.Ref<HTMLInputElement>;
86	  [key: string]: unknown;
87	};
88	
89	type NavLink = {
90	  name: string;
91	  path: string;
92	  icon: React.ComponentType<{ boxSize: number }>;
93	};
94	
95	type OneClickCheckoutConfig = {
96	  enabled?: boolean;
97	};
98	
99	/**
100	 * Search bar for the header.
101	 *
102	 * The search bar is a simple input field with a search icon.
103	 * It can be used to search for products or navigate to a
104	 * specific page.
105	 *
106	 * @param props {object} the component props
107	 * @returns {Element} the search bar element
108	 */
109	// const SearchBar = (props: Record<string, unknown>) => {
110	//   const styles = useMultiStyleConfig('Header');
111	//   const intl = useIntl();
112	//   const placeholder = intl.formatMessage({
113	//     id: 'header.field.placeholder.search_for_products',
114	//     defaultMessage: 'Search for products...',
115	//   });
116	//   return (
117	//     <Box {...styles.searchContainer}>
118	//       <Search aria-label={placeholder} placeholder={placeholder} {...styles.search} {...props} />
119	//     </Box>
120	//   );
121	// };
