123	/**
124	 * The header is the main source for accessing
125	 * navigation, search, basket, and other
126	 * important information and actions. It persists
127	 * on the top of your application and will
128	 * respond to changes in device size.
129	 *
130	 * To customize the styles, update the themes
131	 * in theme/components/project/header.js
132	 * @param  props
133	 * @param   {func} props.onMenuClick click event handler for menu button
134	 * @param   {func} props.onLogoClick click event handler for menu button
135	 * @param   {object} props.searchInputRef reference of the search input
136	 * @param   {func} props.onMyAccountClick click event handler for my account button
137	 * @param   {func} props.onMyCartClick click event handler for my cart button
138	 * @param   {func} props.onAgentClick click event handler for agent button
139	 * @return  {React.ReactElement} - Header component
140	 */
141	const Header = ({
142	  children,
143	  onMenuClick = noop,
144	  onMyAccountClick = noop,
145	  onLogoClick = noop,
146	  onMyCartClick = noop,
147	  onWishlistClick = noop,
148	  onStoreLocatorClick = noop,
149	  onAgentClick = noop,
150	  ...props
151	}: HeaderProps) => {
152	  const intl = useIntl();
153	  const popoverTriggerRef = useRef<HTMLButtonElement>(null);
154	  const {
155	    derivedData: { totalItems },
156	    data: basket,
157	  } = useCurrentBasket();
158	  const { isRegistered } = useCustomerType();
159	  const logout = useAuthHelper(AuthHelpers.Logout);
160	  const navigate = useNavigation();
161	  const appConfig = getConfig().app;
162	  const storeLocatorEnabled = (appConfig?.storeLocatorEnabled as boolean | undefined) ?? STORE_LOCATOR_IS_ENABLED;
163	  const commerceAgentConfig = getCommerceAgentConfig();
164	  const showLaunchAgentButton = commerceAgentConfig?.enableAgentFromHeader === 'true';
165	  const {
166	    getButtonProps: getAccountMenuButtonProps,
167	    getDisclosureProps: getAccountMenuDisclosureProps,
168	    isOpen: isAccountMenuOpen,
169	    onClose: onAccountMenuClose,
170	    onOpen: onAccountMenuOpen,
171	  } = useDisclosure();
172	  // const [isDesktop] = useMediaQuery('(min-width: 992px)'); // unused after layout change: desktop account button always visible
173	
174	  const [showLoading, setShowLoading] = useState(false);
175	  // tracking if users enter the popover Content,
176	  // so we can decide whether to close the menu when users leave account icons
177	  const hasEnterPopoverContent = useRef<boolean>();
178	
179	  const styles = useMultiStyleConfig('Header');
180	  const { oneClickCheckout = {} } = appConfig as { oneClickCheckout?: OneClickCheckoutConfig };
181	  const isOneClickCheckoutEnabled = oneClickCheckout.enabled;
182	
183	  // Filter navigation links based on 1CC configuration
184	  const filteredNavLinks = isOneClickCheckoutEnabled
185	    ? (navLinks as NavLink[])
186	    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');
187	
188	  const onSignoutClick = async () => {
189	    setShowLoading(true);
190	    await logout.mutateAsync();
191	    navigate('/login');
192	    setShowLoading(false);
193	  };
194	
195	  const handleIconsMouseLeave = () => {
196	    // don't close the menu if users enter the popover content
197	    setTimeout(() => {
198	      if (!hasEnterPopoverContent.current) onAccountMenuClose();
199	    }, 100);
200	  };
201	
202	  const handleKeyDown = (event: React.KeyboardEvent) => {
203	    if (event.key === 'Tab' && event.shiftKey && isAccountMenuOpen) {
204	      // Prevent default behavior to keep focus on the popup trigger
205	      event.preventDefault();
206	      popoverTriggerRef.current?.focus();
207	    }
208	  };
209	
210	  return (
211	    <Box as="header" role="banner" {...styles.container} {...props}>
212	      <Box {...styles.content}>
213	        {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
214	
215	        {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
216	        <Flex {...styles.topBar}>
217	          {/* Mobile only: hamburger */}
218	          <IconButton
219	            aria-label={intl.formatMessage({
220	              id: 'header.button.assistive_msg.menu',
221	              defaultMessage: 'Menu',
222	            })}
223	            title={intl.formatMessage({
224	              id: 'header.button.assistive_msg.menu.open_dialog',
225	              defaultMessage: 'Opens a dialog',
226	            })}
227	            icon={<HamburgerIcon />}
228	            variant="unstyled"
229	            display={{ base: 'flex', lg: 'none' }}
230	            {...styles.icons}
231	            onClick={onMenuClick}
232	          />
233	
234	          {/* Desktop left: nav categories (children) + search icon — no flex grow so space-between pushes Account/Saved/Bag to the right */}
235	          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center">
236	            <Box {...styles.bodyContainer}>{children}</Box>
237	            {/* TEMP: debug search input — remove once search overlay is implemented */}
238	            <Box ml={4} minW="240px">
239	              <Search
240	                placeholder={intl.formatMessage({
241	                  id: 'header.field.placeholder.search_for_products',
242	                  defaultMessage: 'Search for products...',
243	                })}
244	              />
245	            </Box>
246	          </Flex>
247	
248	          {/* Desktop right: Account | Saved | Bag as text */}
249	          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center" gap={5}>
250	            {showLaunchAgentButton && (
251	              <IconButton
252	                icon={<SparkleIcon />}
253	                aria-label={intl.formatMessage({
254	                  id: 'header.button.assistive_msg.ask_shopping_agent',
255	                  defaultMessage: 'Ask Shopping Agent',
256	                })}
257	                variant="unstyled"
258	                {...styles.icons}
259	                {...styles.agentIcon}
260	                onClick={onAgentClick}
261	              />
262	            )}
263	            <ButtonWithRegistration
264	              variant="unstyled"
265	              {...styles.desktopActionButton}
266	              onClick={onMyAccountClick}
267	              onMouseOver={onAccountMenuOpen}
268	            >
269	              Account
270	            </ButtonWithRegistration>
271	            {isRegistered && isHydrated() && (
272	              <Popover
273	                isLazy
274	                arrowSize={15}
275	                isOpen={isAccountMenuOpen}
276	                placement="bottom-end"
277	                onClose={onAccountMenuClose}
278	                onOpen={onAccountMenuOpen}
279	              >
280	                <PopoverTrigger>
281	                  <IconButton
282	                    aria-label={intl.formatMessage({
283	                      id: 'header.button.assistive_msg.my_account_menu',
284	                      defaultMessage: 'Open account menu',
285	                    })}
286	                    icon={<ChevronDownIcon />}
287	                    variant="unstyled"
288	                    {...styles.icons}
289	                    {...styles.arrowDown}
290	                    {...getAccountMenuButtonProps()}
291	                    onMouseOver={onAccountMenuOpen}
292	                    onMouseLeave={handleIconsMouseLeave}
293	                    ref={popoverTriggerRef}
294	                    onKeyDown={handleKeyDown}
295	                  />
296	                </PopoverTrigger>
297	
298	                <PopoverContent
299	                  {...styles.popoverContent}
300	                  onMouseLeave={() => {
301	                    hasEnterPopoverContent.current = false;
302	                    onAccountMenuClose();
303	                  }}
304	                  onMouseOver={() => {
305	                    hasEnterPopoverContent.current = true;
306	                  }}
307	                  {...getAccountMenuDisclosureProps()}
308	                >
309	                  <PopoverArrow />
310	                  <PopoverHeader>
311	                    <Text as="h2" fontSize="l" fontFamily="body" fontWeight="700">
312	                      {intl.formatMessage({
313	                        defaultMessage: 'My Account',
314	                        id: 'header.popover.title.my_account',
315	                      })}
316	                    </Text>
317	                  </PopoverHeader>
318	                  <PopoverBody>
319	                    <Box as="nav">
320	                      <Stack spacing={0} as="ul" data-testid="account-detail-nav">
321	                        {filteredNavLinks.map((link) => {
322	                          const LinkIcon = link.icon;
323	                          return (
324	                            <Box key={link.name} position="relative" as="li" listStyleType="none">
325	                              <Button
326	                                as={Link}
327	                                to={`/account${link.path}`}
328	                                useNavLink={true}
329	                                variant="menu-link"
330	                                leftIcon={<LinkIcon boxSize={5} />}
331	                                width="100%"
332	                              >
333	                                {intl.formatMessage(messages[link.name])}
334	                              </Button>
335	                            </Box>
336	                          );
337	                        })}
338	                      </Stack>
339	                    </Box>
340	                  </PopoverBody>
341	                  <PopoverFooter onClick={onSignoutClick} cursor="pointer">
342	                    <Divider colorScheme="gray" />
343	                    <Button variant="unstyled" {...styles.signout}>
344	                      <Flex>
345	                        <SignoutIcon aria-hidden={true} boxSize={5} {...styles.signoutIcon} />
346	                        <Text as="span" {...styles.signoutText}>
347	                          {intl.formatMessage({
348	                            defaultMessage: 'Log out',
349	                            id: 'header.popover.action.log_out',
350	                          })}
351	                        </Text>
352	                      </Flex>
353	                    </Button>
354	                  </PopoverFooter>
355	                </PopoverContent>
356	              </Popover>
357	            )}
358	            <ButtonWithRegistration variant="unstyled" {...styles.desktopActionButton} onClick={onWishlistClick}>
359	              Saved
360	            </ButtonWithRegistration>
361	            <Button variant="unstyled" {...styles.desktopActionButton} onClick={onMyCartClick}>
362	              Bag{basket && totalItems > 0 ? ` (${String(totalItems)})` : ''}
363	            </Button>
364	          </Flex>
365	
366	          {/* Mobile right: icon cluster */}
367	          <Flex display={{ base: 'flex', lg: 'none' }} alignItems="center" gap={2}>
368	            <IconButton
369	              aria-label={intl.formatMessage({
370	                id: 'header.button.assistive_msg.search',
371	                defaultMessage: 'Search',
372	              })}
373	              icon={<SearchIcon />}
374	              variant="unstyled"
375	              {...styles.icons}
376	            />
377	            {/* Base SFCC account/wishlist icon buttons — disabled at copy-first, superseded by the
378	                Account | Saved | Bag text buttons in the Desktop-right block above. HPC-018 requires
379	                Search / Account / Bag in the header; Account ships as text at `lg`+ via that block.
380	                Below `lg` it is absent from the header and only reachable via the burger drawer —
381	                an open HPC-018 question, not a resolved one. See the icons import at the top.
382	                Kept per AGENTS.md's rule on commented-out code. */}
383	            {/* <IconButtonWithRegistration
384	              icon={<AccountIcon />}
385	              aria-label={intl.formatMessage({
386	                id: 'header.button.assistive_msg.my_account',
387	                defaultMessage: 'My Account',
388	              })}
389	              variant="unstyled"
390	              {...styles.icons}
391	              {...styles.accountIcon}
392	              onClick={onMyAccountClick}
393	            />
394	            <IconButtonWithRegistration
395	              aria-label={intl.formatMessage({
396	                defaultMessage: 'Wishlist',
397	                id: 'header.button.assistive_msg.wishlist',
398	              })}
399	              icon={<HeartIcon />}
400	              variant="unstyled"
401	              {...styles.icons}
402	              {...styles.wishlistIcon}
403	              onClick={onWishlistClick}
404	            /> */}
405	            {storeLocatorEnabled && (
406	              <IconButton
407	                aria-label={intl.formatMessage({
408	                  defaultMessage: 'Store Locator',
409	                  id: 'header.button.assistive_msg.store_locator',
410	                })}
411	                icon={<StoreIcon />}
412	                {...styles.icons}
413	                variant="unstyled"
414	                onClick={onStoreLocatorClick}
415	              />
416	            )}
417	            <IconButton
418	              aria-label={intl.formatMessage(
419	                {
420	                  id: 'header.button.assistive_msg.my_cart_with_num_items',
421	                  defaultMessage: 'My cart, number of items: {numItems}',
422	                },
423	                { numItems: totalItems },
424	              )}
425	              icon={
426	                <>
427	                  <BasketIcon />
428	                  {basket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
429	                </>
430	              }
431	              variant="unstyled"
432	              {...styles.icons}
433	              onClick={onMyCartClick}
434	            />
435	          </Flex>
436	        </Flex>
437	
438	        {/* ── Row 2: logo only ────────────────────────────────────────────── */}
439	        <Flex {...styles.logoBar}>
440	          <Button
441	            aria-label={intl.formatMessage({
442	              id: 'header.button.assistive_msg.logo',
443	              defaultMessage: 'Logo',
444	            })}
445	            variant="unstyled"
446	            onClick={onLogoClick}
447	            {...styles.logoButton}
448	          >
449	            <BrandLogo {...styles.logo} />
450	          </Button>
451	        </Flex>
452	
453	        {/* Mobile-only search — commented out, pending searchPopover implementation */}
454	        {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
455	      </Box>
456	    </Box>
457	  );
458	};
459	
460	export default Header;
