235	type DrawerMenuProps = {
236	  /** Accepted only for call-site compatibility with base `_app.jsx` — an SFCC category-tree
237	   *  contract this component no longer reads from. `DrawerMenu` self-fetches its own data via
238	   *  `useHeaderNav()`, so all of these are ignored except `isOpen`/`onClose`/`onLogoClick`. */
239	  root?: Record<string, unknown>;
240	  itemsKey?: string;
241	  itemsCountKey?: string;
242	  itemComponent?: React.ElementType;
243	  isOpen?: boolean;
244	  onClose?: () => void;
245	  onLogoClick?: () => void;
246	};
247	
248	/** Mobile drawer nav — container. Fetches `headerNavItem` entries via `useHeaderNav()` and
249	 *  reads/reports L1<->L2 drill state via `useDrawerMenuState()` (Context, since the header shell
250	 *  that owns the depth state can't reach this component via props through base `_app.jsx`).
251	 *
252	 * @param props see DrawerMenuProps
253	 */
254	const DrawerMenu = ({ isOpen = false, onClose = noop, onLogoClick = noop }: DrawerMenuProps) => {
255	  const { items, isLoading } = useHeaderNav();
256	  const { activeItem, isDrilledIn, drillInto, notifyClosed, registerCloseHandler } = useDrawerMenuState();
257	
258	  // Registers this instance's real onClose so the header shell's LeftBar/RightBar close
259	  // controls (which have no onClose of their own) can trigger the actual Drawer close.
260	  useEffect(() => {
261	    registerCloseHandler(onClose);
262	    return () => registerCloseHandler(null);
263	  }, [onClose, registerCloseHandler]);
264	
265	  // Keeps the header shell's chrome state in sync however the drawer actually closes.
266	  useEffect(() => {
267	    if (!isOpen) notifyClosed();
268	  }, [isOpen, notifyClosed]);
269	
270	  return (
271	    <DrawerMenuView
272	      isOpen={isOpen}
273	      onClose={onClose}
274	      onLogoClick={onLogoClick}
275	      items={items}
276	      isLoading={isLoading}
277	      activeItem={activeItem}
278	      isDrilledIn={isDrilledIn}
279	      onDrillInto={drillInto}
280	    />
281	  );
282	};
283	
284	DrawerMenu.displayName = 'DrawerMenu';
285	
286	export { DrawerMenu };
287	export default DrawerMenu;
