// The Context object useServerContext() (declared above) reads via useContext — needed
// directly (not just through the hook) to seed it with a Storybook-only value, since
// ServerContext has no default and several hooks (e.g. useAppOrigin -> useOrigin)
// unconditionally destructure its value before their own browser-vs-server branch runs.
declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts' {
  import type { Context } from 'react';
  type ServerResponse = {
    set: (name: string, value: string) => void;
    status: (code: number) => ServerResponse;
  };
  export const ServerContext: Context<{ req?: any; res?: ServerResponse } | undefined>;
}

